#include <RetroMediaLab/MediaEngine/PhysicalMedia.h>
#include <RetroMediaLab/MediaEngine/PhysicalMediaIds.h>
#include <RetroMediaLab/MediaEngine/FluxTrackData.h>
#include <RetroMediaLab/MediaEngine/Diagnostics.h>
#include "Constants.h"
#include "../Composition/Runtime.h"
#include "../Models/Flux/Representation.h"
#include "../Primitives/Identifiers.h"
#include <algorithm>
#include <limits>
#include <numeric>
namespace RetroMediaLab::MediaEngine {
namespace P=PhysicalMediaIds;namespace C=PhysicalDetails;
namespace {
[[noreturn]] void invalid(std::string_view field){throw MediaError(DiagnosticCode::PhysicalContract,{std::string(field)});}
void requireRevolution(std::size_t count,int revolution,int cylinder,int head){if(revolution<0)invalid(P::Revolution);if(std::size_t(revolution)>=count)throw MediaError(DiagnosticCode::PhysicalRevolution,{std::to_string(cylinder),std::to_string(head),std::to_string(revolution)});}
std::uint32_t narrow(std::uint64_t value,std::string_view field){if(value>std::numeric_limits<std::uint32_t>::max())invalid(field);return static_cast<std::uint32_t>(value);}
PhysicalDataUnit unit(int cylinder,int head,std::uint32_t period,std::span<const std::uint32_t> ticks,std::uint32_t resolution,std::size_t position,std::stop_token token){if(!resolution)invalid(C::ResolutionField);std::vector<std::uint32_t> intervals;intervals.reserve(ticks.size());for(auto tick:ticks){checkCancellation(token);intervals.push_back(narrow(std::uint64_t(tick)*resolution,C::IntervalField));}FluxTrackData track({FluxRevolutionData(period,std::move(intervals))});return {static_cast<std::int64_t>(position),serializeFluxTrack(track),{{std::string(P::Encoding),std::string(P::FluxTrack)},{std::string(P::Cylinder),std::to_string(cylinder)},{std::string(P::Head),std::to_string(head)},{std::string(P::RevolutionCount),std::string(C::One)},{std::string(P::TickNanoseconds),std::string(C::One)}}};}
PhysicalWritePlan plan(std::vector<PhysicalDataUnit> units){if(units.empty()||units.size()>std::size_t(std::numeric_limits<int>::max()))invalid(C::UnitsField);std::vector<int> order(units.size());std::iota(order.begin(),order.end(),0);return {MediaKind::Floppy,RepresentationKind::Flux,std::move(units),std::move(order)};}
template<class T,class Address> std::vector<const T*> ordered(const std::vector<T>& tracks,Address address){std::vector<const T*> result;result.reserve(tracks.size());for(const auto& track:tracks)result.push_back(&track);std::stable_sort(result.begin(),result.end(),[&](const T* a,const T* b){return address(*a)<address(*b);});return result;}
PhysicalWritePlan fromProtected(const Flux::ProtectedTrackImage& image,int revolution,std::stop_token token){if(revolution<0)invalid(P::Revolution);std::vector<PhysicalDataUnit> units;for(const auto* track:ordered(image.tracks(),[](const auto& t){return std::pair(t.cylinder(),t.head());})){checkCancellation(token);requireRevolution(track->revolutions().size(),revolution,track->cylinder(),track->head());const auto& source=track->revolutions()[revolution];const auto resolution=source.resolutionNanoseconds();if(resolution<=0)invalid(C::ResolutionField);units.push_back(unit(track->cylinder(),track->head(),narrow(std::uint64_t(source.flux().indexTimeTicks)*resolution,C::DurationField),source.flux().intervals,static_cast<std::uint32_t>(resolution),units.size(),token));}return plan(std::move(units));}
}
PhysicalWritePlan createFloppyWritePlan(const DiskCaptureSnapshot& image,int revolution,std::stop_token token){checkCancellation(token);if(revolution<0)invalid(P::Revolution);std::vector<PhysicalDataUnit> units;for(const auto* track:ordered(image.tracks,[](const auto& t){return std::pair(t.cylinder,t.head);})){checkCancellation(token);requireRevolution(track->revolutions.size(),revolution,track->cylinder,track->head);const auto& source=track->revolutions[revolution];if(!source.fluxIntervals||source.resolutionNanoseconds<=0||source.durationNanoseconds<=0)invalid(C::UnitsField);units.push_back(unit(track->cylinder,track->head,narrow(static_cast<std::uint64_t>(source.durationNanoseconds),C::DurationField),*source.fluxIntervals,static_cast<std::uint32_t>(source.resolutionNanoseconds),units.size(),token));}return plan(std::move(units));}
std::future<PhysicalWritePlan> createFloppyWritePlanAsync(std::filesystem::path path,std::optional<std::string> format,int revolution,std::stop_token token){return std::async(std::launch::async,[path=std::move(path),format=std::move(format),revolution,token]{checkCancellation(token);const auto text=path.u8string();if(Primitives::isBlankIdentifier(std::string(text.begin(),text.end())))invalid(C::PathField);auto services=RuntimeDetails::defaultServices();auto document=services->disks.readDocument(path,format,token);if(const auto* flux=dynamic_cast<const FluxRepresentation*>(&document->representation()))return fromProtected(flux->image(),revolution,token);auto explored=services->disks.explore(document,format,{},token);auto tracks=services->sectorEncoder.encodePhysical(*explored.image,token);std::vector<PhysicalDataUnit> units;for(const auto* track:ordered(tracks,[](const auto& t){return std::pair(t.cylinder,t.head);})){const auto& source=track->track.revolution;units.push_back(unit(track->cylinder,track->head,narrow(std::uint64_t(source.indexTimeTicks)*Encoding::Constants::TickNanoseconds,C::DurationField),source.intervals,Encoding::Constants::TickNanoseconds,units.size(),token));}return plan(std::move(units));});}
}
